     const pb = buffers.get(it.bubble ? it.bubble.id : '');
     if (!pb) continue;
     const role = it.bubble && project.roles.find(r => r.id === it.bubble.roleId);
     mixAdd(pb.buffer, it.t + pb.offset, clampVol(role && role.volume));
   }
