     try {
       const m = await decodeToBuffer(actx, settings.musicBlob);
       const g = (settings.mvol ?? 15) / 100 * 0.6;
       // зациклить по длительности
       let pos = 0; while (pos < total) { mixAdd(m, pos, g); pos += m.duration; }
     } catch (e) {}
   }

