 function encodeWav(pcm, sr) {
   const buf = new ArrayBuffer(44 + pcm.length * 2);
   const d = new DataView(buf);
   const ws = (o, s) => { for (let i = 0; i < s.length; i++) d.setUint8(o + i, s.charCodeAt(i)); };
