   d.setUint32(24, sr, true); d.setUint32(28, sr * 2, true); d.setUint16(32, 2, true); d.setUint16(34, 16, true);
   ws(36, 'data'); d.setUint32(40, pcm.length * 2, true);
   for (let i = 0; i < pcm.length; i++) d.setInt16(44 + i * 2, pcm[i], true);
   return buf;
 }

