display.text:
/* Чат с ИИ: сессии, сообщения, файловые вложения (без лимитов). */

import { idbGet, idbSet, chatGetSessions, chatSetSessions, chatGetMessages, chatSetMessages, chatDelSession, KEY_SETTINGS } from './store.js';
import { provider, chat, chatWithImage, modelMeta } from './ai.js';
import { openModelPicker } from './modelsui.js';

const LS_CURRENT = 'chat:current';
const MAX_COPY = 12;

const $ = (id) => document.getElementById(id);
let sessions = [];
let currentId = null;
let messages = [];
let attachments = []; // { file, name, type, dataURL? }
let asking = false;

export async function initChat() {
  sessions = await chatGetSessions();
  currentId = (idbGet && (await idbGet(LS_CURRENT))) || null;
  if (!currentId || !sessions.find(s => s.id === currentId)) {
    currentId = sessions[0] ? sessions[0].id : null;
  }
  if (currentId) { await loadMessages(); } else { currentId = newChat(); await loadMessages(); }
  renderModelButton();
  renderSessions();
  renderMessages();
  wireChat();
}

function newChat() {
  const s = { id: 's' + Date.now(), title: 'Сессия ' + new Date().toLocaleString('ru', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }), ts: Date.now() };
  sessions.unshift(s);
  persistSessions();
  return s.id;
}

async function persistSessions() {
  await chatSetSessions(sessions);
  if (currentId) await idbSet(LS_CURRENT, currentId);
}

async function loadMessages() {
  messages = await chatGetMessages(currentId);
}

async function persistMessages() {
  await chatSetMessages(currentId, messages);
}

let S = {}; // текущие настройки (обновляются из app.js)

/* Кнопка-пикер модели чата (вместо огромного списка «все провайдеры × все модели»). */
function renderModelButton() {
  const btn = $('btnChatPickModel');
  if (!btn) return;
  const pid = S.ai || 'pollinations';
  const p = provider(pid);
  const mid = S.aimodel || (p.models[0] ? p.models[0].id : 'openai');
  const mt = modelMeta(pid, mid);
  btn.textContent = '🔍 ' + (mt.nokey ? '🆓 ' : '') + (mt.label || mid) + ' — ' + mt.providerName;
  btn.style.overflow = 'hidden';
  btn.style.textOverflow = 'ellipsis';
  btn.style.maxWidth = '70vw';
  btn.title = (mt.free ? 'Бесплатно' : 'Платно') + (mt.vision ? ' · vision' : '') + ' · ' + pid + ' / ' + mid;
}

function renderSessions() {
  const sel = $('chat-sessions');
  if (!sel) return;
  sel.replaceChildren();
  for (const s of sessions) {
    const o = document.createElement('option');
    o.value = s.id;
    o.textContent = s.title;
    o.selected = s.id === currentId;
    sel.appendChild(o);
  }
  const empty = $('chat-empty');
  if (empty) empty.classList.toggle('hidden', messages.length > 0);
}

function renderMessages() {
  const box = $('chat-messages');
  const empty = $('chat-empty');
  if (!box) return;
  box.replaceChildren();
  if (messages.length === 0) { if (empty) empty.classList.remove('hidden'); return; }
  if (empty) empty.classList.add('hidden');
  messages.forEach((m, i) => {
    const d = document.createElement('div');
    d.className = 'msg ' + (m.role === 'user' ? 'user' : m.role === 'err' ? 'err' : 'ai');
    if (m.typing) d.classList.add('typing');
    let h = '<span class="who">' + (m.role === 'user' ? 'Вы' : m.role === 'err' ? 'Ошибка' : 'ИИ') + '</span>';
    if (m.files && m.files.length && m.role === 'user') {
      for (const f of m.files) {
        if (f.dataURL || f.objectUrl) {
          h += '<img class="att" src="' + (f.dataURL || f.objectUrl) + '" alt="…">';
        } else {
          h += '<span class="attfile">📎 ' + escapeHtml(f.name) + ' · ' + fmtSize(f.size) + '</span>';
        }
      }
    }
    if (i === messages.length - 1 && messages[messages.length - 1].typing && !m.content) {
      // пусто пока печатает
    }
    h += '<div>' + escapeHtml(m.content || (m.typing ? '…' : '')) + '</div>';
    if (m.content && m.role === 'ai' && m.content.length > 60) h += '<span class="mtime">' + new Date(m.ts).toLocaleTimeString('ru', { hour: '2-digit', minute: '2-digit' }) + '</span>';
    d.innerHTML = h;
    box.appendChild(d);
  });
  box.scrollTop = box.scrollHeight;
}

function resolveModel() {
  return { provider: S.ai, model: S.aimodel };
}

async function ask() {
  if (asking) return;
  const input = $('chat-input');
  const text = (input ? input.value : '').trim();
  if (!text && !attachments.length) return;
  asking = true;
  if (input) input.value = '';
  const files = attachments.splice(0);
  renderAttachments();
  const userMsg = { role: 'user', content: text, files, ts: Date.now() };
  messages.push(userMsg);
  await persistMessages();
  renderMessages();
  const typing = { role: 'ai', typing: true, ts: Date.now() };
  messages.push(typing);
  renderMessages();
  try {
    const { provider: pid, model: mid } = resolveModel();
    const chatSettings = { ...S, ai: pid, aimodel: mid };
    const history = messages.filter(m => !m.typing && m.role !== 'err' && m.role !== 'system')
      .filter((m, i, arr) => i >= Math.max(0, arr.length - MAX_COPY));
    const sys = messages.find(m => m.role === 'system');
    const systemPrompt = 'Ты — помощник пользователя приложения VoiceComic (комиксы → озвученное видео). Отвечай по-русски, коротко и по делу. Пользователь может присылать изображения и файлы: изображения разбирай как страницы манги/комикса, текстовые файлы прочитывай и комментируй.';
    void sys;
    const files = userMsg.files || [];
    const images = files.filter(f => f.dataURL);
    let answer;
    if (images.length) {
      answer = await chatWithImage(chatSettings, [
        { role: 'system', content: systemPrompt },
        ...history.map(m => ({ role: m.role, content: m.content })),
      ], images[0].dataURL);
    } else {
      answer = await chat(chatSettings, [
        { role: 'system', content: systemPrompt },
        ...history.map(m => ({ role: m.role, content: m.content })),
      ]);
    }
    messages = messages.filter(m => m !== typing);
    messages.push({ role: 'ai', content: String(answer), ts: Date.now() });
    const title = (text || (files[0] && files[0].name) || 'Сессия').trim().slice(0, 40);
    if (currentId && sessions.find(sp => sp.id === currentId)) {
      const sp = sessions.find(x => x.id === currentId);
      if (sp.title.startsWith('Сессия ') || !sp.title) { sp.title = title; sp.ts = Date.now(); }
      sessions.sort((a, b) => b.ts - a.ts);
      await persistSessions();
      renderSessions();
    }
  } catch (e) {
    messages = messages.filter(m => m !== typing);
    messages.push({ role: 'err', content: 'Ошибка: ' + (e.message || e), ts: Date.now() });
    console.error(e);
  }
  asking = false;
  await persistMessages();
  renderMessages();
}

function renderAttachments() {
  const box = $('chat-attachments');
  if (!box) return;
  box.replaceChildren();
  attachments.forEach((a, i) => {
    const s = document.createElement('span');
    s.className = 'att';
    s.textContent = '📎 ' + a.name + ' · ' + fmtSize(a.size);
    const x = document.createElement('button');
    x.className = 'btn mini';
    x.style.padding = '0 6px';
    x.textContent = '✕';
    x.addEventListener('click', () => { attachments.splice(i, 1); renderAttachments(); });
    s.appendChild(x);
    box.appendChild(s);
  });
}

function escapeHtml(s) { return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
function fmtSize(n) { return n > 1048576 ? (n / 1048576).toFixed(1) + ' МБ' : n > 1024 ? Math.round(n / 1024) + ' КБ' : n + ' Б'; }

function wireChat() {
  const input = $('chat-input');
  const send = $('btnChatSend');
  const del = $('btnChatDel');
  const file = $('chat-file');
  const sessionsSel = $('chat-sessions');
  const modelBtn = $('btnChatPickModel');
  const btnNew = $('btnChatNew');

  if (send) send.addEventListener('click', () => ask());
  if (input) input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); ask(); }
  });
  if (modelBtn) modelBtn.addEventListener('click', () => {
    if (asking) return;
    openModelPicker({
      settings: S || {},
      onSelect: async (pid, mid) => {
        S = { ...S, ai: pid, aimodel: mid };
        renderModelButton();
        try {
          await idbSet(KEY_SETTINGS, S);
        } catch (e) { console.warn(e); }
        if (window.onSettingsChanged) window.onSettingsChanged(S);
      },
    });
  });
  if (file) file.addEventListener('change', () => {
    for (const f of file.files) {
      if (!attachments.find(a => a.file === f)) {
        const a = { file: f, name: f.name, size: f.size, type: f.type };
        if (f.type.startsWith('image/')) {
          const rd = new FileReader();
          rd.onload = () => { a.dataURL = rd.result; };
          rd.readAsDataURL(f);
        }
        attachments.push(a);
      }
    }
    file.value = '';
    renderAttachments();
  });
  if (sessionsSel) sessionsSel.addEventListener('change', async () => {
    currentId = sessionsSel.value;
    await persistSessions();
    await loadMessages();
    renderSessions();
    renderMessages();
  });
  if (btnNew) btnNew.addEventListener('click', async () => {
    currentId = newChat();
    await persistSessions();
    await loadMessages();
    renderSessions();
    renderMessages();
  });
  if (del) del.addEventListener('click', async () => {
    if (!currentId) return;
    if (!confirm('Удалить текущую сессию чата?')) return;
    await chatDelSession(currentId);
    const list = sessions.filter(s => s.id !== currentId);
    sessions = list;
    currentId = list[0] ? list[0].id : (newChat(), currentId);
    if (!list[0]) { currentId = sessions[0].id; }
    await persistSessions();
    await loadMessages();
    renderSessions();
    renderMessages();
  });
}

/* вызывается из app.js при старте и при изменении настроек */
export function setChatSettings(s) { S = s || {}; renderModelButton(); }

export const chatApi = { initChat, renderAttachments, setChatSettings };

const CACHE = 'voicecomic-v5';
const CORE = [
  './',
  'index.html',
  'css/ui.css',
  'js/util.js',
  'js/store.js',
  'js/ai.js',
  'js/models.dev.js',
  'js/import.js',
  'js/ocr.js',
  'js/voices.js',
  'js/engine.js',
  'js/yolo.js',
  'js/app.js',
  'js/modelsui.js',
  'js/chat.js',
  'manifest/manifest.webmanifest',
  'icon.svg'
];

self.addEventListener('install', (e) => {
  e.waitUntil(
    caches.open(CACHE).then((c) =>
      // каждый файл по отдельности: отсутствие одного не должно валить установку SW
      Promise.all(CORE.map((u) => c.add(u).catch(() => {})))
    ).then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    const keys = await caches.keys();
    const stale = keys.filter((k) => k !== CACHE);
    await Promise.all(stale.map((k) => caches.delete(k)));
    await self.clients.claim();
    // Старая версия отдавала оболочку из кэша (cache-first): после обновления
    // уже открытые страницы надо перезагрузить, иначе APK/PWA продолжает
    // показывать прошлую версию. Ждать навигацию внутри waitUntil нельзя —
    // активация и загрузка страницы начинают ждать друг друга и SW зависает
    // в состоянии «activating».
    if (stale.length) {
      try {
        const wins = await self.clients.matchAll({ type: 'window' });
        for (const w of wins) {
          try {
            const p = w.navigate(w.url);
            if (p && typeof p.catch === 'function') p.catch(() => {});
          } catch (err) { /* WebView без Client.navigate — обновится при следующем старте */ }
        }
      } catch (err) { /* ignore */ }
    }
  })());
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return;
  e.respondWith(networkFirst(req, e));
});

/* Сеть первым, кэш — только как запасной вариант на случай офлайна.
 * В APK «сеть» — это свежие файлы из установленного пакета, поэтому
 * приложение всегда стартует с актуальной версией. */
async function networkFirst(req, e) {
  const cache = await caches.open(CACHE);
  try {
    const res = await fetch(req);
    const cacheable = res && (res.ok || res.type === 'opaque');
    if (cacheable && !req.headers.get('range')) {
      try { e.waitUntil(cache.put(req, res.clone())); } catch (err) { /* нет waitUntil */ }
    }
    return res;
  } catch (err) {
    const hit = await cache.match(req, { ignoreSearch: req.mode === 'navigate' });
    if (hit) return hit;
    if (req.mode === 'navigate') {
      const shell = (await cache.match('index.html')) || (await cache.match('./')) || (await cache.match('/'));
      if (shell) return shell;
    }
    return new Response('', { status: 504, statusText: 'Offline' });
  }
}

#!/usr/bin/env node
/* Zen-релей для VoiceComic.
 *
 * OpenCode Zen free tier («демо-режим», модели big-pickle, mimo-v2.5-free и
 * др.) пускает запросы БЕЗ ключа только при условии, что они «выглядят» как
 * запросы opencode-CLI: нужны identity-заголовки (User-Agent: opencode/<ver>,
 * x-opencode-session/request/client/project), stream:true, tool_choice:auto и
 * официальный набор builtin-тулов. Браузер не может подменить User-Agent, а у
 * zen нет CORS — поэтому для keyless-моделей из PWA/APK нужен этот релей.
 *
 * Понимает два эндпоинта zen (выбираются автоматически по модели):
 *   - /v1/chat/completions — oa-compat модели (big-pickle, mimo-*, nemotron-*,
 *     ling-*, space-bunny-free, deepseek-v4-flash-free);
 *   - /v1/responses       — Responses-модели (muse-spark-*-contributor-free;
 *     тулы конвертируются в Responses-формат и поднимается max_output_tokens);
 *   - jev-*               — это «система решений» структуры state+questions,
 *     не чат; релей возвращает понятную ошибку.
 * Оба пути сворачиваются в обычный JSON chat.completion, так что клиент
 * (non-stream) ничего не знает про SSE.
 *
 * Запуск:        node relay/zen-relay.mjs [порт]
 *                 (порт по умолчанию 8789; можно ZEN_RELAY_PORT=…)
 * Проверка:      curl -s localhost:8789/healthz
 * Пример:
 *   POST http://localhost:8789/v1/chat/completions
 *   { "model":"big-pickle","messages":[{"role":"user","content":"привет"}] }
 *   — демо-модели без ключа; платные — если прислать Authorization: Bearer <ключ Zen>.
 */

import http from 'node:http';
import crypto from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const PORT = Number(process.argv[2] || process.env.ZEN_RELAY_PORT || 8789);
const ZEN = 'https://opencode.ai/zen/v1';
const OPENCODE_VERSION = '1.18.31';
const TOOLS = JSON.parse(readFileSync(path.join(ROOT, 'builtin_tools.json'), 'utf8'));

const RESPONSES_MODELS = /muse-spark-\S*contributor-free/;
const JEV_MODELS = /^jev-/;

const B62 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
function ocId(prefix) {
  const packed = Date.now() * 0x1000;
  let tail = '';
  for (const b of crypto.randomBytes(14)) tail += B62[b % 62];
  return prefix + packed.toString(16).padStart(12, '0').slice(-12) + tail;
}

const PROBE_MSG = { type: 'user', content: 'ping' };

function cors(res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', '*');
  res.setHeader('Access-Control-Expose-Headers', '*');
}

function sendJson(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(body);
}

async function readBody(req) {
  const chunks = [];
  for await (const c of req) chunks.push(c);
  return Buffer.concat(chunks);
}

function identityHeaders(req) {
  const h = {
    'Content-Type': 'application/json',
    'User-Agent': `opencode/${OPENCODE_VERSION}`,
    'x-opencode-client': 'cli',
    'x-opencode-project': 'global',
    'x-opencode-session': ocId('ses_'),
    'x-opencode-request': ocId('msg_'),
    Accept: 'application/json, text/event-stream',
  };
  if (req.headers.authorization) h.Authorization = req.headers.authorization;
  return h;
}

function mergeTools(clientTools) {
  if (Array.isArray(clientTools) && clientTools.length) return [...clientTools];
  return TOOLS;
}

function responsesTools() {
  return TOOLS.map((t) => ({
    type: 'function',
    name: t.function.name,
    description: t.function.description,
    parameters: t.function.parameters,
  }));
}

function sseFoldChat(raw) {
  let content = '';
  let finish_reason = 'stop';
  for (const line of raw.split(/\r?\n/)) {
    const s = line.trim();
    if (!s.startsWith('data:')) continue;
    const payload = s.slice(5).trim();
    if (!payload || payload === '[DONE]') continue;
    try {
      const o = JSON.parse(payload);
      const d = o.choices && o.choices[0];
      if (!d) continue;
      if (d.delta && d.delta.content) content += d.delta.content;
      if (d.finish_reason) finish_reason = d.finish_reason;
    } catch (_) { /* skip partial */ }
  }
  return { content, finish_reason };
}

function sseFoldResponses(raw) {
  let content = '';
  let status = 'completed';
  let stopped = false;
  for (const line of raw.split(/\r?\n/)) {
    const s = line.trim();
    if (!s.startsWith('data:')) continue;
    const payload = s.slice(5).trim();
    if (!payload || payload === '[DONE]') continue;
    try {
      const o = JSON.parse(payload);
      if (o.type === 'response.output_text.delta') content += o.delta || '';
      if (o.type === 'response.completed') { status = (o.response && o.response.status) || 'completed'; stopped = true; }
      if (o.type === 'response.failed') { status = 'failed'; stopped = true; }
    } catch (_) { /* skip partial */ }
  }
  return { content, status, stopped };
}

function completionJson(model, result) {
  return {
    id: 'chatcmpl-relay-' + Date.now(),
    object: 'chat.completion',
    created: Math.floor(Date.now() / 1000),
    model,
    choices: [{
      index: 0,
      message: { role: 'assistant', content: result.content || '' },
      finish_reason: result.finish_reason || 'stop',
    }],
    usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
  };
}

async function handleChat(req, res) {
  let body;
  try {
    body = JSON.parse((await readBody(req)).toString('utf8') || '{}');
  } catch (e) {
    return sendJson(res, 400, { error: { type: 'invalid_request_error', message: 'Bad JSON body' } });
  }

  const model = body.model || '';
  if (typeof model !== 'string' || !model.trim()) {
    return sendJson(res, 400, { error: { type: 'invalid_request_error', message: 'model is required' } });
  }
  if (JEV_MODELS.test(model)) {
    return sendJson(res, 400, {
      error: { type: 'model_not_chat', message: `«${model}» (Jev) — это не чат-модель, а «система решений» (state+questions); в VoiceComic не используется.` },
    });
  }

  const h = identityHeaders(req);
  const isResponses = RESPONSES_MODELS.test(model);

  let out;
  let upstreamUrl;
  if (isResponses) {
    upstreamUrl = ZEN + '/responses';
    out = {
      ...body,
      model,
      stream: true,
      tools: responsesTools(),
      tool_choice: 'auto',
      // без запас по токенам muse-модели возвращают «incomplete»
      max_output_tokens: Math.max(body.max_output_tokens || 800, 800),
      input: Array.isArray(body.messages) && body.messages.length
        ? body.messages.map((m) => ({
            role: m.role || 'user',
            content: [{ type: 'input_text', text: textOf(m.content) }],
          }))
        : [{ role: 'user', content: [{ type: 'input_text', text: 'ping' }] }],
    };
    delete out.messages;
    delete out.max_tokens;
  } else {
    upstreamUrl = ZEN + '/chat/completions';
    out = {
      ...body,
      model,
      stream: true,
      tool_choice: body.tool_choice || 'auto',
      tools: mergeTools(body.tools),
      messages: (body.messages && body.messages.length) ? body.messages : [PROBE_MSG],
    };
    delete out.unused;
  }

  let upstream;
  try {
    upstream = await fetch(upstreamUrl, {
      method: 'POST',
      headers: h,
      body: JSON.stringify(out),
      signal: AbortSignal.timeout(90000),
    });
  } catch (e) {
    return sendJson(res, 502, { error: { type: 'relay_error', message: 'Upstream unreachable: ' + e.message } });
  }

  const raw = await upstream.text();
  if (upstream.status !== 200) {
    const ct = (upstream.headers.get('content-type') || '').toLowerCase();
    let payload = { error: { type: 'upstream_error', message: `Zen HTTP ${upstream.status}` } };
    if (ct.includes('json')) {
      try { payload = JSON.parse(raw); } catch (_) { /* keep default */ }
    }
    return sendJson(res, upstream.status, payload);
  }

  const result = isResponses ? sseFoldResponses(raw) : sseFoldChat(raw);
  return sendJson(res, 200, completionJson(model, result));
}

function textOf(content) {
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) {
    return content.map((p) => (p && p.text != null ? p.text : '')).join('\n');
  }
  return String(content || '');
}

const server = http.createServer(async (req, res) => {
  cors(res);
  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    return res.end();
  }
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/healthz') {
    return sendJson(res, 200, { ok: true, zen: ZEN, version: OPENCODE_VERSION, tools: TOOLS.length });
  }
  if (req.method === 'POST' && url.pathname === '/v1/chat/completions') {
    return handleChat(req, res);
  }
  return sendJson(res, 404, { error: { type: 'not_found', message: url.pathname } });
});

server.listen(PORT, () => {
  console.log('zen-relay on :' + PORT + ' → ' + ZEN);
  console.log('демо-модели без ключа:');
  console.log('  chat: big-pickle, mimo-v2.5-free, mimo-v2.6-flash-free, nemotron-3-ultra-free,');
  console.log('        nemotron-3.5-lightning-free, ling-3.0-flash-fin-free, space-bunny-free, deepseek-v4-flash-free');
  console.log('  responses: muse-spark-1.3-contributor-free, muse-spark-1.2-contributor-free');
  console.log('  jev-* — decision-модель, не чат (не поддерживается)');
});

