   return {
     pid,
     mid,
     label: m.label || mid,
     providerName: (p.name || pid).split(' ·')[0],
     nokey: p.key === false || m.nokey === true,
     free: modelKind(pid, mid) === 'free',
     paid: modelKind(pid, mid) === 'paid',
     vision: p.vision === true,
     curated: p.curated === true,
     requiresKey: p.key === true,
