   const arr = bubbles.map((b, i) => ({ b, i }));
   const pageW = Math.max(...arr.map(a => a.b.x + a.b.w)) || 1;
   const pageH = Math.max(...arr.map(a => a.b.y + a.b.h)) || 1;

