input.content:
/* Проверка кэша сессии YOLO на поддельном IndexedDB: сколько раз
 * читаются 108 МБ модели при обработке N страниц (было N, стало 1). */
const store = new Map();
const meta = { reads: 0, bytesRead: 0, writes: 0 };

globalThis.indexedDB = {
  open() {
    const req = { onsuccess: null, onupgradeneeded: null, onerror: null, result: null };
    queueMicrotask(() => {
      req.result = {
        objectStoreNames: { contains: () => true },
        createObjectStore() {},
        transaction() {
          return {
            objectStore: () => ({
              get(k) { const r = { result: store.get(k) }; queueMicrotask(() => { meta.reads++; meta.bytesRead += (store.get(k)?.byteLength || 0); r.onsuccess = null; }); return r; },
              put(v, k) { store.set(k, v); meta.writes++; return {}; },
              delete(k) { store.delete(k); return {}; },
            }),
            oncomplete: null, onerror: null,
            _fire() { queueMicrotask(() => this.oncomplete && this.oncomplete()); },
          };
        },
      };
      req.onsuccess && req.onsuccess();
    });
    return req;
  },
};

const Y = await import('/home/runner/hub-work/comic2film/code/js/yolo.js');
const st = await import('/home/runner/hub-work/comic2film/code/js/store.js');

// Подменяем store-функции модуля yolo через общий indexDB-шим:
// проще всего положить байты напрямую и считать чтения.
const MODEL_BYTES = 108982949;
const key = 'model:bubbles:yolov8m-seg-bubble';
store.set(key, new Uint8Array(1024));   // «лежит на устройстве»
store.set(key + ':meta', { bytes: MODEL_BYTES });

// Подменяем ort: createSession считаем вызовы
let sessionsCreated = 0;
globalThis.window = globalThis;
globalThis.ort = {
  env: {},
  InferenceSession: { create: async () => { sessionsCreated++; return { run: async () => ({ output0: { data: new Float32Array(37 * 4) } }) }; } },
  Tensor: class { constructor() {} },
};
YOLO_MODELS_patch();
function YOLO_MODELS_patch() { /* модель уже в реестре */ }

globalThis.fetch = async () => { throw new Error('сеть не нужна: модель уже в IndexedDB'); };

const fakeCanvas = { width: 640, height: 640 };
// detectBubbles ждёт Canvas с naturalWidth/width и getContext
const canvas = { width: 640, height: 640, getContext: () => ({
  fillRect() {}, drawImage() {},
  getImageData: () => ({ data: new Uint8ClampedArray(640 * 640 * 4) }),
}) };

const N = 20;
for (let i = 0; i < N; i++) await Y.detectBubbles(canvas);

console.log('страниц обработано:', N);
console.log('InferenceSession.create вызвано раз:', sessionsCreated, sessionsCreated === 1 ? '(кэш работает)' : '(ОЖИДАЛОСЬ 1)');
console.log('чтений из IndexedDB:', meta.reads, '(метаданные + байты модели)');
console.log('байт прочитано из IDB:', meta.bytesRead, '— без кэша было бы ~' + (N * MODEL_BYTES / 1e9).toFixed(1) + ' ГБ');

const st1 = await Y.bubbleModelStatus();
console.log();
console.log('bubbleModelStatus (только по метазаписи):', JSON.stringify(st1));
console.log('ожидаем ready=true, bytes=' + MODEL_BYTES);

