   const segs = sliceSegments(body, sr, { threshold: 0.02, minSilence: 0.3, minClip: 0.3 });
   const mapped = segs.map(s => ({ startS: s.startS + trimmed.start / sr, endS: s.endS + trimmed.start / sr }));
