+  const m = /^(\d+)\.(\d+)\.(\d+)/.exec(String(pkg.version || '0.0.0'));
+  const [major, minor, patch] = m ? [Number(m[1]), Number(m[2]), Number(m[3])] : [0, 0, 0];
+  return { name: `${major}.${minor}.${patch}`, code: major * 10000 + minor * 100 + patch };
