/* Проверка zen-relay: сбой больше не отдаётся как 200 с пустым ответом. */
import { spawn } from 'node:child_process';

const PORT = 8792;
const srv = spawn('node', ['/home/runner/hub-work/comic2film/code/relay/zen-relay.mjs', String(PORT)], { stdio: ['ignore', 'pipe', 'pipe'] });
await new Promise(r => srv.stdout.once('data', r));
await new Promise(r => setTimeout(r, 300));

let fails = 0;
const ok = (c, n) => { console.log((c ? 'ok   ' : 'FAIL ') + n); if (!c) fails++; };

const post = (body) => fetch(`http://localhost:${PORT}/v1/chat/completions`, {
  method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
});

console.log('=== 1. /healthz ===');
const h = await fetch(`http://localhost:${PORT}/healthz`).then(r => r.json());
ok(h.ok === true && h.tools > 0, 'healthz: ok=' + h.ok + ' tools=' + h.tools);

console.log('\n=== 2. jev-модель отклоняется с внятной ошибкой ===');
const jev = await post({ model: 'jev-something', messages: [{ role: 'user', content: 'x' }] });
const jevBody = await jev.json();
ok(jev.status === 400 && /не чат-модель/.test(jevBody.error.message), 'jev: HTTP ' + jev.status + ' — ' + jevBody.error.message.slice(0, 60));

console.log('\n=== 3. нет model → 400 ===');
const nm = await post({ messages: [] });
ok(nm.status === 400, 'без model: HTTP ' + nm.status);

console.log('\n=== 4. битый JSON → 400 ===');
const bad = await fetch(`http://localhost:${PORT}/v1/chat/completions`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{не json' });
ok(bad.status === 400, 'битый JSON: HTTP ' + bad.status);

console.log('\n=== 5. сетевой сбой апстрима → 502, не 200 ===');
const up = await post({ model: 'big-pickle', messages: [{ role: 'user', content: 'привет' }] }).catch(e => ({ status: 0, err: e }));
if (up.status === 200) {
  const b = await up.json();
  const empty = (b.choices[0].message.content || '') === '';
  ok(!empty, 'реальный ответ непустой, HTTP 200');
  ok(typeof b.usage.total_tokens === 'number' && b.usage.total_tokens > 0, 'usage:不再是 нули — total_tokens=' + b.usage.total_tokens + ' estimated=' + b.usage.estimated);
  ok(b.choices[0].finish_reason === 'stop', 'finish_reason=' + b.choices[0].finish_reason);
  console.log('     ответ: ' + JSON.stringify(b.choices[0].message.content).slice(0, 100));
} else if (up.status === 502) {
  const b = await up.json().catch(() => ({}));
  ok(!!b.error && !!b.error.message, 'апстрим недоступен → 502 с сообщением: ' + (b.error && b.error.message || '').slice(0, 80));
