  ok(false, 'неожиданный статус ' + up.status + ' ' + (up.err || ''));
}

console.log('\n=== 6. 404 на неизвестный путь ===');
ok((await fetch(`http://localhost:${PORT}/nope`)).status === 404, '404');

srv.kill();
console.log('\n' + (fails ? fails + ' FAILURES' : 'ALL PASS'));
process.exit(fails ? 1 : 0);

/* Юнит-тесты сворачивания SSE в zen-relay: сбой не должен становиться
