ok(!!r.error && /boom/.test(r.error), 'responses: response.failed → ошибка');

r = R.sseFoldResponses(sse('data: {"type":"response.incomplete","response":{"incomplete_details":{"reason":"max_output_tokens"}}}'));
ok(!!r.error && /max_output_tokens/.test(r.error), 'responses: incomplete → ошибка с причиной');

r = R.sseFoldResponses(sse('data: {"type":"response.completed","response":{"status":"in_progress"}}'));
ok(!!r.error, 'responses: незавершённый статус → ошибка');

r = R.sseFoldResponses(sse('data: [DONE]'));
ok(!!r.error && /пустой/.test(r.error), 'responses: пусто → ошибка');

console.log('\n=== usage больше не нули ===');
const c = R.completionJson('big-pickle', { content: 'Привет, мир!', finish_reason: 'stop' });
ok(c.usage.total_tokens > 0 && c.usage.estimated === true, 'usage: total_tokens=' + c.usage.total_tokens + ', помечено estimated');
ok(c.choices[0].message.content === 'Привет, мир!' && c.object === 'chat.completion', 'completionJson: формат ответа цел');
const c2 = R.completionJson('m', { content: 'x', usage: { input_tokens: 11, output_tokens: 7 } });
ok(c2.usage.total_tokens === 18 && !c2.usage.estimated, 'usage: если апстрим дал числа — они используются как есть');

console.log('\n' + (fails ? fails + ' FAILURES' : 'ALL PASS'));
process.exit(fails ? 1 : 0);

