let lastBody = null;
globalThis.fetch = async (url, opt) => {
  lastBody = { url: String(url), body: JSON.parse(opt.body) };
  return { ok: true, status: 200, json: async () => ({ choices: [{ message: { content: 'ок' } }] }) };
};

// store.js нужен для import чата
const store = new Map();
globalThis.indexedDB = {
  open() {
    const req = {};
    queueMicrotask(() => {
      req.result = {
        objectStoreNames: { contains: () => true },
        createObjectStore() {},
        transaction() {
          const tx = { objectStore: () => ({
            get(k) { return { result: store.get(k) }; },
            put(v, k) { store.set(k, v); return {}; },
            delete(k) { store.delete(k); return {}; },
          }), oncomplete: null, onerror: null };
          setTimeout(() => { if (tx.oncomplete) tx.oncomplete(); }, 0);
          return tx;
        },
      };
      req.onsuccess && req.onsuccess();
    });
    return req;
  },
};

// минимальный DOM для чата
const nodes = {};
for (const id of ['chat-input', 'btnChatSend', 'chat-messages', 'chat-empty', 'chat-attachments', 'chat-sessions', 'chat-file', 'btnChatDel', 'btnChatNew', 'btnChatPickModel']) {
