/* Умные/быстрые: известно поведение для типовых имён. */
const mtSmart = ai.modelMeta('openai', 'gpt-5.2');
const mtFast = ai.modelMeta('openai', 'gpt-4o-mini');
const mtFlash = ai.modelMeta('gemini', 'gemini-2.0-flash');
