/* Настраивает release-подпись в regenerated Capacitor-проекте (android/).
 * Вызывается после `npx cap add android` / `npx cap sync android`.
 * Keystore и пароли берутся из android/keystore.properties (НЕ коммитится).
 * Формат keystore.properties:
 *   STORE_FILE=../keystore/voicecomic-release.jks
 *   STORE_PASSWORD=...
 *   KEY_ALIAS=voicecomic
 *   KEY_PASSWORD=...
 * Если файла нет — release собирается без подписи (fallback). */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';

const gradle = 'android/app/build.gradle';
const props = 'android/keystore.properties';

if (!existsSync(gradle)) {
  console.error('нет ' + gradle);
  process.exit(0);
}

let g = readFileSync(gradle, 'utf8');

if (!/(versionName|versionCode)/.test(g)) {
  g = g.replace(
    'targetSdkVersion rootProject.ext.targetSdkVersion',
    'targetSdkVersion rootProject.ext.targetSdkVersion\n        versionCode 1\n        versionName "1.0.0"'
  );
} else {
  g = g.replace(/versionName\s+"[^"]*"/, 'versionName "1.0.0"');
  g = g.replace(/versionCode\s+\d+/, 'versionCode 1');
}

if (!g.includes('signingConfigs')) {
  g += `
def keystoreProps = new Properties()
def keystorePropsFile = rootProject.file('keystore.properties')
if (keystorePropsFile.exists()) {
  keystoreProps.load(keystorePropsFile.newInputStream())
} else {
  keystoreProps.STORE_FILE   = System.getenv('KEYSTORE_FILE') ?: ''
  keystoreProps.STORE_PASSWORD = System.getenv('KEYSTORE_PASSWORD') ?: ''
  keystoreProps.KEY_ALIAS    = System.getenv('KEY_ALIAS') ?: ''
  keystoreProps.KEY_PASSWORD = System.getenv('KEY_PASSWORD') ?: ''
}
android {
  signingConfigs {
    release {
      if (keystoreProps.STORE_FILE?.trim()) {
        storeFile rootProject.file(keystoreProps.STORE_FILE)
        storePassword keystoreProps.STORE_PASSWORD
        keyAlias keystoreProps.KEY_ALIAS
        keyPassword keystoreProps.KEY_PASSWORD
      }
    }
  }
  buildTypes {
    release {
      signingConfig signingConfigs.release
    }
  }
}
`;
  writeFileSync(gradle, g);
  console.log('release signing patched');
} else {
  console.log('release signing already present');
}

const CACHE = 'voicecomic-v5';
const CORE = [
  './',
  'index.html',
  'css/ui.css',
  'js/util.js',
  'js/store.js',
  'js/ai.js',
  'js/models.dev.js',
  'js/import.js',
  'js/ocr.js',
  'js/voices.js',
  'js/engine.js',
  'js/yolo.js',
  'js/app.js',
  'js/modelsui.js',
  'js/chat.js',
  'manifest/manifest.webmanifest',
  'icon.svg'
];

self.addEventListener('install', (e) => {
  e.waitUntil(
    caches.open(CACHE).then((c) =>
      // каждый файл по отдельности: отсутствие одного не должно валить установку SW
      Promise.all(CORE.map((u) => c.add(u).catch(() => {})))
    ).then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    const keys = await caches.keys();
    const stale = keys.filter((k) => k !== CACHE);
    await Promise.all(stale.map((k) => caches.delete(k)));
    await self.clients.claim();
    // Старая версия отдавала оболочку из кэша (cache-first): после обновления
    // уже открытые страницы надо перезагрузить, иначе APK/PWA продолжает
    // показывать прошлую версию. Ждать навигацию внутри waitUntil нельзя —
    // активация и загрузка страницы начинают ждать друг друга и SW зависает
    // в состоянии «activating».
    if (stale.length) {
      try {
        const wins = await self.clients.matchAll({ type: 'window' });
        for (const w of wins) {
          try {
            const p = w.navigate(w.url);
            if (p && typeof p.catch === 'function') p.catch(() => {});
          } catch (err) { /* WebView без Client.navigate — обновится при следующем старте */ }
        }
      } catch (err) { /* ignore */ }
    }
  })());
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return;
  e.respondWith(networkFirst(req, e));
});

/* Сеть первым, кэш — только как запасной вариант на случай офлайна.
 * В APK «сеть» — это свежие файлы из установленного пакета, поэтому
 * приложение всегда стартует с актуальной версией. */
async function networkFirst(req, e) {
  const cache = await caches.open(CACHE);
  try {
    const res = await fetch(req);
    const cacheable = res && (res.ok || res.type === 'opaque');
    if (cacheable && !req.headers.get('range')) {
      try { e.waitUntil(cache.put(req, res.clone())); } catch (err) { /* нет waitUntil */ }
    }
    return res;
  } catch (err) {
    const hit = await cache.match(req, { ignoreSearch: req.mode === 'navigate' });
    if (hit) return hit;
    if (req.mode === 'navigate') {
      const shell = (await cache.match('index.html')) || (await cache.match('./')) || (await cache.match('/'));
      if (shell) return shell;
    }
    return new Response('', { status: 504, statusText: 'Offline' });
  }
}

