:root{
  --bg:#0f1420; --bg2:#161d2e; --panel:#1b2438; --panel2:#202a41;
  --line:#2c3a5e; --txt:#e8edf7; --mut:#93a0b8;
  --acc:#5b8cff; --acc2:#8f6bff; --ok:#3ecf9a; --warn:#ffb454; --bad:#ff6b7a;
  --r:14px;
}
*{box-sizing:border-box; -webkit-tap-highlight-color:transparent}
html,body{margin:0;padding:0;height:100%;touch-action:manipulation}
body{
  background:var(--bg); color:var(--txt);
  font:16px/1.45 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
}
#app{max-width:760px;margin:0 auto;min-height:100%;display:flex;flex-direction:column;
  padding-bottom:calc(64px + env(safe-area-inset-bottom));}
.hidden{display:none!important}

/* header */
#topbar{position:sticky;top:0;z-index:30;display:flex;align-items:center;gap:10px;
  padding:10px 14px;padding-top:calc(10px + env(safe-area-inset-top));
  background:rgba(15,20,32,.92);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}
.brand{display:flex;gap:10px;align-items:center}
.brand .logo{font-size:24px}
.t1{font-weight:800;letter-spacing:.3px}
.t2{font-size:11px;color:var(--mut)}
.spacer{flex:1}
button{color:var(--txt);background:var(--panel);border:1px solid var(--line);
  border-radius:10px;padding:8px 12px;font-size:14px;cursor:pointer;touch-action:manipulation}
button:active{transform:scale(.97)}
button:disabled{opacity:.5;pointer-events:none}
button.icon{border:none;background:transparent;font-size:20px}
button.primary{background:linear-gradient(135deg,var(--acc),var(--acc2));border:none;font-weight:700}
button.big{padding:14px 18px;font-size:16px;width:100%}
button.mini{padding:6px 10px;font-size:13px;background:var(--panel2);border-color:var(--line)}
button.file{position:relative;overflow:hidden}
button.file input{position:absolute;opacity:0;inset:0;cursor:pointer}
button.danger{border-color:var(--bad);color:var(--bad);background:transparent}
button.ghost{color:var(--mut)}

main{flex:1;padding:14px;padding-bottom:24px}
.tab{display:none}
.tab.active{display:block;animation:fade .18s ease}
@keyframes fade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}

.card{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);
  padding:14px;margin-bottom:14px}
.card h2{margin:0 0 8px;font-size:16px}
.muted{color:var(--mut);font-size:13px;margin:4px 0}
.hint{color:var(--mut);font-size:12px;margin-top:8px}
.empty{color:var(--mut);text-align:center;padding:24px 8px;font-size:14px}

/* dropzone */
.dropzone{border:2px dashed var(--line);border-radius:var(--r);padding:26px 14px;
  text-align:center;cursor:pointer;transition:.15s;background:var(--bg2)}
.dropzone.drag{border-color:var(--acc);background:#182136}
.dz-icon{font-size:38px}
.dz-text{color:var(--mut);margin:8px 0 12px}

/* bottom tabs */
#tabsbar{position:fixed;bottom:0;left:0;right:0;z-index:30;display:flex;
  background:rgba(15,20,32,.96);backdrop-filter:blur(10px);border-top:1px solid var(--line)}

