@media(min-width:761px){#tabsbar{max-width:760px;left:50%;transform:translateX(-50%);border-radius:14px 14px 0 0}}

/* grids & lists */
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:8px}
.grid .page{position:relative;border-radius:8px;overflow:hidden;aspect-ratio:3/4;background:var(--bg2);
  border:1px solid var(--line)}
.grid .page img{width:100%;height:100%;object-fit:contain;display:block}
.grid .page .pn{position:absolute;left:4px;top:4px;background:rgba(0,0,0,.6);border-radius:6px;
  font-size:11px;padding:1px 6px}
.grid .page .dot{position:absolute;right:4px;top:4px;width:9px;height:9px;border-radius:50%;
  background:#555}
.grid .page .dot.on{background:var(--ok)}
.grid .page .rm{position:absolute;right:4px;bottom:4px;background:rgba(0,0,0,.55);border:none;
  border-radius:6px;font-size:11px;padding:1px 7px;color:#ddd}
.list{display:flex;flex-direction:column;gap:8px}
.list .item{background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:10px}
.item.rowrow{display:flex;gap:8px;align-items:flex-start}
.item .chn{padding:10px;text-align:center;color:var(--mut)}

.row{display:flex;align-items:center;gap:8px}
.row.wrap{flex-wrap:wrap}
.row.head{margin-bottom:8px;justify-content:space-between}
.seg{display:inline-flex;border:1px solid var(--line);border-radius:10px;overflow:hidden}
.seg.small button{font-size:12px;padding:5px 9px}
.seg button{border:none;border-radius:0;background:transparent}
.seg button.active{background:var(--acc);font-weight:700}

/* forms */
.form{display:flex;flex-direction:column;gap:7px}
.form label{font-size:13px;color:var(--mut);margin-top:4px}
.field{display:flex;flex-direction:column;gap:7px}
.form .field label{font-size:13px;color:var(--mut);margin-top:4px}
.form input, .form select{
  background:var(--bg2);border:1px solid var(--line);color:var(--txt);
  border-radius:10px;padding:9px 10px;font-size:15px;width:100%;touch-action:manipulation}
input[type=range]{padding:0;height:32px;accent-color:var(--acc);touch-action:manipulation}
textarea{background:var(--bg2);border:1px solid var(--line);color:var(--txt);
  border-radius:10px;padding:9px 10px;font-size:15px;width:100%;touch-action:manipulation}

/* progress */
.loadbar{height:10px;border-radius:6px;background:var(--bg2);overflow:hidden;border:1px solid var(--line)}
.loadbar .fill{height:100%;width:0;background:linear-gradient(90deg,var(--acc),var(--acc2));transition:width .2s}
.log{font-family:ui-monospace,Menlo,monospace;font-size:12px;color:var(--mut);
  max-height:220px;overflow:auto;white-space:pre-wrap;margin-top:8px}

/* roles */
.role{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.role .emo{font-size:26px;width:38px;text-align:center}

/* modal */
#modal{position:fixed;inset:0;background:rgba(5,8,16,.7);z-index:60;display:flex;align-items:center;justify-content:center;padding:16px}
#modal-box{background:var(--panel);border:1px solid var(--line);border-radius:16px;width:100%;max-width:520px;max-height:90vh;display:flex;flex-direction:column}
#modal-head{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border-bottom:1px solid var(--line)}
#modal-body{padding:14px;overflow:auto}
#modal-body.cv{display:flex;justify-content:center;background:#000}

/* toast */
#toast{position:fixed;left:50%;bottom:80px;transform:translateX(-50%);z-index:80;
  background:#222c42;border:1px solid var(--acc);color:var(--txt);padding:10px 16px;
  border-radius:12px;font-size:14px;max-width:88vw;box-shadow:0 8px 30px rgba(0,0,0,.5)}
#toast.ok{border-color:var(--ok)} #toast.err{border-color:var(--bad)}

/* bubbles overlay on editor canvas */
#bubbles-overlay{position:fixed;inset:0;z-index:70;background:#000;display:flex;flex-direction:column}
#bubbles-overlay .ov-top{display:flex;gap:8px;padding:10px;align-items:center}
#bubbles-overlay canvas{flex:1;width:100%;background:#111;object-fit:contain}

a{color:var(--acc)}
#dl-link{display:block;margin-top:10px;font-weight:700}
/* chat */
.chat-messages{display:flex;flex-direction:column;gap:8px;max-height:52vh;overflow-y:auto;border:1px solid var(--line);border-radius:12px;padding:10px;background:var(--bg2)}
.msg{max-width:86%;padding:8px 11px;border-radius:12px;font-size:14px;line-height:1.45;white-space:pre-wrap;word-break:break-word}
.msg.user{align-self:flex-end;background:var(--acc);color:#06121f}
.msg.ai{align-self:flex-start;background:var(--panel2);border:1px solid var(--line);color:var(--txt)}
.msg.err{align-self:flex-start;background:rgba(210,70,90,.12);border:1px solid var(--bad);color:var(--bad)}
.msg .who{font-size:11px;opacity:.7;margin-bottom:2px;display:block}
.msg .mtime{font-size:10px;opacity:.55;display:block;margin-top:4px}
.msg img.att{max-width:100%;max-height:160px;border-radius:8px;margin:4px 0;display:block}
.msg .attfile{display:inline-flex;align-items:center;gap:6px;background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:3px 8px;font-size:12px;margin:2px 4px 2px 0}
.msg.typing{opacity:.6}
.chat-attachments .att{display:inline-flex;align-items:center;gap:6px;background:var(--panel2);border:1px solid var(--line);border-radius:8px;padding:4px 8px;font-size:12px;margin:2px 4px 2px 0}
.flex1{flex:1;min-width:0}

/* terminal modal */
#term-modal{position:fixed;inset:0;background:rgba(5,8,16,.85);z-index:70;display:flex;align-items:center;justify-content:center;padding:16px}
#term-modal-box{background:#1e1e1e;border:1px solid var(--line);border-radius:12px;width:100%;max-width:1000px;height:80vh;max-height:80vh;display:flex;flex-direction:column;overflow:hidden}
#term-modal-head{display:flex;justify-content:space-between;align-items:center;padding:10px 12px;border-bottom:1px solid var(--line);flex-wrap:wrap;gap:8px}
#term-modal-head .mini{padding:4px 8px;font-size:12px}
#term-container{flex:1;overflow:hidden;background:#1e1e1e}
#term-container .xterm{height:100%}
.mini{padding:4px 8px;font-size:12px}

/* model picker */
.mp-rows{max-height:52vh;overflow:auto;display:flex;flex-direction:column;gap:6px;margin-top:4px}
.mp-row{display:flex;align-items:center;gap:10px;background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:8px 10px;cursor:pointer;transition:.12s}
.mp-row:active{transform:scale(.99)}
.mp-row.sel{border-color:var(--acc);background:#18233c}
.mp-row .grow{flex:1;min-width:0}
.mp-short{color:var(--mut);font-size:12px}
.mp-tag{display:inline-block;font-size:11px;line-height:1.5;padding:0 7px;border-radius:999px;border:1px solid var(--line);margin:1px 3px 1px 0;background:var(--bg)}
.mp-tag.green{color:var(--ok);border-color:var(--ok)}
.mp-tag.blue{color:var(--acc);border-color:var(--acc)}
.mp-tag.red{color:var(--bad);border-color:var(--bad)}
.mp-tag.warn{color:var(--warn);border-color:var(--warn)}
.mp-ok{color:var(--ok);font-size:13px;white-space:nowrap}
.mp-bad{color:var(--bad);font-size:13px;white-space:nowrap}

/* вкладки провайдеров */
.mp-tabs{display:flex;gap:6px;overflow-x:auto;padding-bottom:4px;scrollbar-width:thin}
.mp-tab{display:flex;align-items:center;gap:6px;white-space:nowrap;background:var(--panel2);
  border:1px solid var(--line);border-radius:999px;padding:5px 10px;font-size:13px}
.mp-tab.active{background:linear-gradient(135deg,var(--acc),var(--acc2));border-color:transparent;font-weight:700}
.mp-tab .mp-tabb{font-size:12px;opacity:.85}

/* чипсы-фильтры */
.mp-chips{display:flex;gap:6px;overflow-x:auto;flex-wrap:nowrap;padding-bottom:2px;scrollbar-width:thin}
.mp-chip{white-space:nowrap;background:var(--panel2);border:1px solid var(--line);border-radius:999px;
  padding:4px 10px;font-size:12px}
.mp-chip.active{background:var(--acc);border-color:transparent;font-weight:700}
.mp-qual{background:var(--bg2);border:1px solid var(--line);color:var(--txt);border-radius:10px;
  padding:6px 8px;font-size:13px}
.mp-actions{display:flex;gap:6px;flex-wrap:wrap;align-items:center}

/* деревья/группы внутри провайдера */
.mp-provh{background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:8px 10px}
.mp-provt{margin-bottom:4px}
.mp-provb{margin-bottom:4px}
.mp-provh .mp-key{display:inline-block;margin-top:4px;font-size:13px;font-weight:700}
.mp-provh .mp-provm{font-size:11px;word-break:break-all}
.mp-tree{display:flex;flex-direction:column;gap:4px}
.mp-tree details{background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:4px 6px}
.mp-tree details summary{list-style:none;cursor:pointer;padding:4px 6px;font-size:13px}
.mp-tree details summary::-webkit-details-marker{display:none}
.mp-tree details summary::before{content:'▸ ';color:var(--acc)}
.mp-tree details[open] summary::before{content:'▾ ';color:var(--acc)}
.mp-grp{display:flex;align-items:center;gap:8px}
.mp-hint{background:var(--bg2);border:1px dashed var(--line);border-radius:10px;
  padding:8px 10px;font-size:12px;color:var(--mut)}
@media(min-width:601px){.mp-tabs{flex-wrap:wrap}.mp-chips{flex-wrap:wrap}}
